export interface Bet {
  id: string;
  numbers: number[];
  createdAt: number;
  type: 'manual' | 'random' | 'ai';
  reasoning?: string;
}

export interface AIRootResponse {
  numbers: number[];
  reasoning: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { AIRootResponse } from "../types";

const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
};

export const generateLuckyNumbersWithAI = async (quantity: number = 6): Promise<AIRootResponse> => {
  const ai = getAIClient();

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Gere ${quantity} números únicos para a Mega Sena (entre 1 e 60). Forneça também uma explicação mística ou estatística criativa (em português) de por que esses números foram escolhidos para dar sorte ao jogador.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          numbers: {
            type: Type.ARRAY,
            items: { type: Type.INTEGER },
            description: "Array de números sugeridos (1-60)."
          },
          reasoning: {
            type: Type.STRING,
            description: "Explicação criativa sobre a escolha dos números."
          }
        },
        required: ["numbers", "reasoning"]
      }
    }
  });

  try {
    const data = JSON.parse(response.text || '{}');
    return {
      numbers: data.numbers.sort((a: number, b: number) => a - b),
      reasoning: data.reasoning
    };
  } catch (error) {
    console.error("Erro ao processar resposta do Gemini", error);
    // Fallback em caso de erro
    const fallbacks = Array.from({ length: quantity }, () => Math.floor(Math.random() * 60) + 1);
    return {
      numbers: Array.from(new Set(fallbacks)).sort((a, b) => a - b),
      reasoning: "A sorte é um mistério! Estes números foram selecionados aleatoriamente."
    };
  }
};

import React from 'react';

interface NumberBallProps {
  num: number;
  isSelected?: boolean;
  onClick?: () => void;
  size?: 'sm' | 'md' | 'lg';
}

const NumberBall: React.FC<NumberBallProps> = ({ num, isSelected, onClick, size = 'md' }) => {
  const sizeClasses = {
    sm: 'w-8 h-8 text-xs',
    md: 'w-10 h-10 text-sm md:w-12 md:h-12 md:text-base',
    lg: 'w-14 h-14 text-lg md:w-16 md:h-16 md:text-xl'
  };

  return (
    <button
      onClick={onClick}
      className={`
        flex items-center justify-center rounded-full font-bold transition-all duration-200 shadow-md
        ${sizeClasses[size]}
        ${isSelected 
          ? 'bg-emerald-600 text-white border-2 border-emerald-400 scale-110' 
          : 'bg-white text-emerald-800 border-2 border-emerald-100 hover:border-emerald-300'
        }
      `}
    >
      {num.toString().padStart(2, '0')}
    </button>
  );
};

export default NumberBall;

import React from 'react';
