          >
            <ListChecks size={18} className="inline mr-2" />
            Apostar
          </button>
          <button 
            onClick={() => setShowHistory(true)}
            className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${showHistory ? 'bg-emerald-600 text-white' : 'text-emerald-800 hover:bg-emerald-50'}`}
          >
            <History size={18} className="inline mr-2" />
