              <div className="bg-white rounded-3xl p-6 border border-emerald-100 shadow-lg">
                <h3 className="text-lg font-bold text-emerald-900 mb-4 flex items-center">
                  <Dice5 className="mr-2 text-emerald-600" size={22} />
                  Surpresinha
                </h3>
                <p className="text-gray-500 text-sm mb-6">
                  Gere rapidamente uma combinação aleatória de {betCount} números.
                </p>
                <button 
                  onClick={generateSurpresinha}
                  className="w-full bg-emerald-50 text-emerald-700 py-3 rounded-2xl font-bold hover:bg-emerald-100 transition-all border border-emerald-200 flex items-center justify-center space-x-2"
                >
                  <Dice5 size={20} />
