                </button>
              </div>

              <div className="bg-emerald-900 rounded-3xl p-6 text-white shadow-lg">
                <h4 className="flex items-center text-sm font-bold uppercase tracking-widest text-emerald-400 mb-3">
                  <Info size={16} className="mr-2" />
