import { GoogleGenAI, Type } from "@google/genai";
import { AIRootResponse, AnalysisResult } from "../types";

const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
};

export const generateLuckyNumbersWithAI = async (quantity: number = 6): Promise<AIRootResponse> => {
  const ai = getAIClient();

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Acesse e analise as estatísticas mais recentes da Mega Sena no site https://www.numeromania.com.br/sena.html. 
    Considere dados cruciais como:
    1. Números mais sorteados (os que mais saíram na história).
    2. Números mais atrasados (os que não saem há mais tempo).
    3. Tendências e combinações frequentes citadas no site.

    Com base nessas estatísticas reais, gere ${quantity} números únicos (entre 1 e 60) para uma aposta vencedora. 
    Forneça também uma explicação detalhada (em português) justificando a escolha de cada grupo de números com base nos dados que você encontrou no Numeromania.`,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          numbers: {
            type: Type.ARRAY,
            items: { type: Type.INTEGER },
            description: "Array de números sugeridos (1-60)."
          },
          reasoning: {
            type: Type.STRING,
            description: "Explicação técnica/estatística sobre a escolha dos números baseada na pesquisa no site Numeromania."
          }
        },
        required: ["numbers", "reasoning"]
      }
    }
  });

  try {
    const data = JSON.parse(response.text || '{}');

    // Extract grounding URLs from the grounding metadata
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    const groundingUrls = groundingChunks?.map((chunk: any) => {
      if (chunk.web) {
        return { uri: chunk.web.uri, title: chunk.web.title };
      }
      return null;
    }).filter(Boolean) || [];

    return {
      numbers: data.numbers.sort((a: number, b: number) => a - b),
      reasoning: data.reasoning,
      groundingUrls
    };
  } catch (error) {
    console.error("Erro ao processar resposta do Gemini", error);
    const fallbacks: number[] = [];
    while (fallbacks.length < quantity) {
      const r = Math.floor(Math.random() * 60) + 1;
      if (!fallbacks.includes(r)) fallbacks.push(r);
    }
    return {
      numbers: fallbacks.sort((a, b) => a - b),
      reasoning: "A sorte é um mistério! Tivemos um problema técnico ao acessar os dados em tempo real, então estes números foram gerados aleatoriamente.",
      groundingUrls: []
    };
  }
};

export const analyzeBetHistory = async (numbers: number[]): Promise<AnalysisResult> => {
  const ai = getAIClient();
  const numbersStr = numbers.join(', ');

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Verifique se a combinação de números [${numbersStr}] já premiou na história da Mega Sena acessando o site https://asloterias.com.br/todos-resultados-mega-sena. 
    Analise se houve acertos de:
    - Sena (6 números)
    - Quina (5 números)
    - Quadra (4 números)
    - Terno (3 números)

    Retorne a quantidade de vezes que cada uma dessas combinações ocorreu na história completa do sorteio.`,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          hasSena: { type: Type.BOOLEAN },
          hasQuina: { type: Type.BOOLEAN },
          hasQuadra: { type: Type.BOOLEAN },
          hasTerno: { type: Type.BOOLEAN },
          matchCounts: {
            type: Type.OBJECT,
            properties: {
              sena: { type: Type.INTEGER },
              quina: { type: Type.INTEGER },
              quadra: { type: Type.INTEGER },
              terno: { type: Type.INTEGER }
            },
            required: ["sena", "quina", "quadra", "terno"]
          },
          details: { type: Type.STRING, description: "Resumo em texto dos resultados encontrados." }
        },
        required: ["hasSena", "hasQuina", "hasQuadra", "hasTerno", "matchCounts", "details"]
      }
    }
  });

  try {
    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("Erro na análise histórica", error);
    throw error;
  }
};

