import React, { useState, useEffect, useMemo } from 'react';
import { Sparkles, Dice5, RotateCcw, Save, Trash2, ListChecks, History, Info, Filter, ArrowUpDown, Activity } from 'lucide-react';
import { generateLuckyNumbersWithAI, analyzeBetHistory } from './services/geminiService';
import { Bet } from './types';
import NumberBall from './components/NumberBall';
import BetCard from './components/BetCard';

const STORAGE_KEY = 'mega_sorte_bets';

type FilterType = 'all' | 'manual' | 'ai' | 'random';
type DateRange = 'all' | 'today' | 'week' | 'month';
type SortOrder = 'newest' | 'oldest';

const App: React.FC = () => {
  const [selectedNumbers, setSelectedNumbers] = useState<number[]>([]);
  const [betCount, setBetCount] = useState<number>(6);
  const [history, setHistory] = useState<Bet[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [analyzingId, setAnalyzingId] = useState<string | null>(null);
  const [loadingStatus, setLoadingStatus] = useState("");
  const [showHistory, setShowHistory] = useState(false);

  const [filterType, setFilterType] = useState<FilterType>('all');
  const [dateRange, setDateRange] = useState<DateRange>('all');
  const [sortOrder, setSortOrder] = useState<SortOrder>('newest');

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch (e) {
        console.error("Error parsing history", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(history));
  }, [history]);

  const toggleNumber = (num: number) => {
    if (selectedNumbers.includes(num)) {
      setSelectedNumbers(prev => prev.filter(n => n !== num));
    } else {
      if (selectedNumbers.length < 20) {
        setSelectedNumbers(prev => [...prev, num].sort((a, b) => a - b));
      } else {
        alert("O limite máximo de números por aposta na Mega Sena é 20.");
      }
    }
  };

  const clearSelection = () => {
    setSelectedNumbers([]);
  };

  const saveBet = (type: Bet['type'], numbers: number[], reasoning?: string, groundingUrls?: Bet['groundingUrls']) => {
    const newBet: Bet = {
      id: Math.random().toString(36).substr(2, 9),
      numbers: [...numbers].sort((a, b) => a - b),
      createdAt: Date.now(),
      type,
      reasoning,
      groundingUrls
    };
    setHistory(prev => [newBet, ...prev]);
  };

  const handleManualSave = () => {
    if (selectedNumbers.length < 6) {
      alert("Selecione pelo menos 6 números.");
      return;
    }
    saveBet('manual', selectedNumbers);
    clearSelection();
  };

  const generateSurpresinha = () => {
    const numbers: number[] = [];
    while (numbers.length < betCount) {
      const r = Math.floor(Math.random() * 60) + 1;
      if (!numbers.includes(r)) numbers.push(r);
    }
    const sorted = numbers.sort((a, b) => a - b);
    setSelectedNumbers(sorted);
    saveBet('random', sorted);
    setShowHistory(true);
  };

  const generateAI = async () => {
    setIsLoading(true);
    setLoadingStatus("Acessando Numeromania...");
    try {
      const result = await generateLuckyNumbersWithAI(betCount);
      setSelectedNumbers(result.numbers);
      saveBet('ai', result.numbers, result.reasoning, result.groundingUrls);
      setShowHistory(true);
    } catch (error) {
      alert("Erro ao conectar com a IA. Tente novamente mais tarde.");
    } finally {
      setIsLoading(false);
      setLoadingStatus("");
    }
  };

  const handleAnalyzeBet = async (id: string) => {
    const bet = history.find(b => b.id === id);
    if (!bet) return;

    setAnalyzingId(id);
    try {
      const result = await analyzeBetHistory(bet.numbers);
      setHistory(prev => prev.map(b => b.id === id ? { ...b, analysis: result } : b));
    } catch (error) {
      alert("Falha na consulta ao site asloterias.com.br. Tente novamente.");
    } finally {
      setAnalyzingId(null);
    }
  };

  const deleteBet = (id: string) => {
    setHistory(prev => prev.filter(b => b.id !== id));
  };

  const clearHistory = () => {
    if (confirm("Deseja apagar todo o histórico de apostas?")) {
      setHistory([]);
    }
  };

  const filteredHistory = useMemo(() => {
    let result = [...history];

    if (filterType !== 'all') {
      result = result.filter(bet => bet.type === filterType);
    }

    const now = Date.now();
    const oneDay = 24 * 60 * 60 * 1000;
    const oneWeek = 7 * oneDay;
    const oneMonth = 30 * oneDay;

    if (dateRange === 'today') {
      result = result.filter(bet => now - bet.createdAt < oneDay);
    } else if (dateRange === 'week') {
      result = result.filter(bet => now - bet.createdAt < oneWeek);
    } else if (dateRange === 'month') {
      result = result.filter(bet => now - bet.createdAt < oneMonth);
    }

    result.sort((a, b) => {
      return sortOrder === 'newest' ? b.createdAt - a.createdAt : a.createdAt - b.createdAt;
    });

    return result;
  }, [history, filterType, dateRange, sortOrder]);

