import { GoogleGenAI, Type } from "@google/genai";
import { AIRootResponse, AnalysisResult } from "../types";

const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
};

export const generateLuckyNumbersWithAI = async (quantity: number = 6): Promise<AIRootResponse> => {
  const ai = getAIClient();

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Acesse e analise as estatísticas mais recentes da Mega Sena no site https://www.numeromania.com.br/sena.html. 
    Considere dados cruciais como:
    1. Números mais sorteados e números mais atrasados.
    2. A tendência de SOMA das dezenas: estatisticamente, a soma dos 6 números costuma gravitar entre 150 e 210.

    Com base nisso, gere ${quantity} números únicos (1-60). 
    A soma desses números deve estar preferencialmente na faixa de 150 a 210.
    Forneça também uma explicação justificando a escolha baseada nos dados do Numeromania e na análise da soma total das dezenas.`,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          numbers: {
            type: Type.ARRAY,
            items: { type: Type.INTEGER },
            description: "Array de números sugeridos (1-60)."
          },
          reasoning: {
            type: Type.STRING,
            description: "Explicação estatística incluindo comentário sobre a soma das dezenas."
          }
        },
        required: ["numbers", "reasoning"]
      }
    }
  });

  try {
    const data = JSON.parse(response.text || '{}');
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    const groundingUrls = groundingChunks?.map((chunk: any) => {
      if (chunk.web) return { uri: chunk.web.uri, title: chunk.web.title };
      return null;
    }).filter(Boolean) || [];

    return {
      numbers: data.numbers.sort((a: number, b: number) => a - b),
      reasoning: data.reasoning,
      groundingUrls
    };
  } catch (error) {
    console.error("Erro no Gemini", error);
    const fallbacks: number[] = [];
    while (fallbacks.length < quantity) {
      const r = Math.floor(Math.random() * 60) + 1;
      if (!fallbacks.includes(r)) fallbacks.push(r);
    }
    return {
      numbers: fallbacks.sort((a, b) => a - b),
      reasoning: "A sorte é um mistério! Tivemos um problema técnico, mas estes números seguem uma distribuição aleatória.",
      groundingUrls: []
    };
  }
};

export const analyzeBetHistory = async (numbers: number[]): Promise<AnalysisResult> => {
  const ai = getAIClient();
  const numbersStr = numbers.join(', ');

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Verifique se a combinação [${numbersStr}] já premiou na Mega Sena usando https://asloterias.com.br/todos-resultados-mega-sena. 
    Compare também a soma total desses números com a média dos últimos 100 sorteios do site.`,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          hasSena: { type: Type.BOOLEAN },
          hasQuina: { type: Type.BOOLEAN },
          hasQuadra: { type: Type.BOOLEAN },
          hasTerno: { type: Type.BOOLEAN },
          matchCounts: {
            type: Type.OBJECT,
            properties: {
              sena: { type: Type.INTEGER },
              quina: { type: Type.INTEGER },
              quadra: { type: Type.INTEGER },
              terno: { type: Type.INTEGER }
            },
            required: ["sena", "quina", "quadra", "terno"]
          },
          details: { type: Type.STRING }
        },
        required: ["hasSena", "hasQuina", "hasQuadra", "hasTerno", "matchCounts", "details"]
      }
    }
  });

  try {
    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("Erro na análise", error);
    throw error;
  }
};

