  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { Sparkles, Dice5, RotateCcw, Save, Trash2, ListChecks, History, Info, Filter, ArrowUpDown, Activity, FileJson, Layers } from 'lucide-react';
