                <button onClick={() => { if(confirm("Deseja limpar todo o histórico?")) setHistory([]) }} className="text-red-500 font-black text-[10px] uppercase hover:underline flex items-center space-x-1">
                  <Trash2 size={14} /> <span>LIMPAR</span>
                </button>
              </div>
            </div>

            {filteredHistory.length === 0 ? (
