                  <BetCard key={bet.id} bet={bet} onDelete={(id) => setHistory(h => h.filter(x => x.id !== id))} onAnalyze={handleAnalyzeBet} isAnalyzing={analyzingId === bet.id} />
                ))}
              </div>
            )}
          </div>
        )}
      </main>

      <footer className="mt-auto py-10 text-center no-print">
        <p className="text-emerald-900/40 text-[9px] font-black uppercase tracking-widest mb-2">
          Mega Sorte AI • Filtro de Soma & Estatística • 2024
        </p>
      </footer>
    </div>
  );
};

