                </div>
                <div className="absolute -right-10 -bottom-10 w-40 h-40 bg-white/10 rounded-full blur-3xl"></div>
              </div>

              <div className="bg-white rounded-3xl p-6 border border-emerald-100 shadow-lg space-y-3">
